function upgradeState(){for(const c of state.contracts){c.quality=c.quality||DEFAULT_QUALITY;c.docs=Array.isArray(c.docs)&&c.docs.length?c.docs:[...DEFAULT_DOCS];c.packings=Array.isArray(c.packings)?c.packings:[];for(const p of c.packings)p.masterBag=p.masterBag||{enabled:false,qty:0,tare:0}}for(const s of state.shipments){const c=contractByRef(s.contractRef)||{};s.lc=s.lc||{saved:false,documents:[],conditions:[]};s.loading=s.loading||{lots:[],draft:null};s.loading.lots=Array.isArray(s.loading.lots)?s.loading.lots:[];s.millActuals=Array.isArray(s.millActuals)?s.millActuals:[];s.customs=Object.assign({saved:false,date:TODAY(),invoiceNo:`CI-${String(s.contractRef).replace(/\W/g,'-')}`,currency:c.currency||'USD',rate:c.packings?.[0]?.price||0,fiAllocations:[],gdRefs:[],bank:'',iban:'',hsCode:'',marks:'',description:c.product||''},s.customs||{});s.bl=Object.assign({draftSaved:false,finalized:false,blNo:'',onBoardDate:'',vessel:'',voyage:'',consignee:'TO ORDER',notify:s.buyer||'',description:c.product||'',finalFile:''},s.bl||{});s.commercial=Object.assign({saved:false,date:TODAY(),rate:c.packings?.[0]?.price||0,invoiceNo:c.ref||s.contractRef,bankInvoices:[]},s.commercial||{});s.coo=Object.assign({saved:false,date:TODAY(),reference:'',description:c.product||''},s.coo||{});s.certs=Array.isArray(s.certs)?s.certs:[];s.covering=Object.assign({saved:false,dispatched:false,dispatchDate:'',sentThrough:'DHL',tracking:'',bank:'',remarks:'',docs:[]},s.covering||{})}save()}
function cleanText(v){return String(v||'').replace(/\r/g,'\n').replace(/[ \t]+/g,' ').replace(/\n{3,}/g,'\n\n').trim()}
function lines(v){return cleanText(v).split('\n').map(x=>x.trim()).filter(Boolean)}
function fieldValue(text,labels){const ls=lines(text);for(const label of labels){const re=new RegExp('^(?:'+label+')\\s*(?::|-)?\\s*(.+)$','i');for(const line of ls){const m=line.match(re);if(m?.[1])return m[1].trim()}}return''}
function firstNumber(v){const m=String(v||'').replace(/,/g,'').match(/\d+(?:\.\d+)?/);return m?Number(m[0]):0}
function parseDate(v){const s=String(v||'');let m=s.match(/(20\d{2})[-\/.](\d{1,2})[-\/.](\d{1,2})/);if(m)return`${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;m=s.match(/(\d{1,2})[-\/.](\d{1,2})[-\/.](20\d{2})/);return m?`${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`:''}
function paymentFromText(text){const u=String(text).toUpperCase(),raw=fieldValue(text,['PAYMENT(?: TERMS?)?','TERMS OF PAYMENT']);if(/USANCE|DEFERRED|\d+\s*DAYS.*(?:B\/?L|BILL OF LADING)/.test(u))return{paymentCode:'LC_USANCE',usanceDays:firstNumber((u.match(/\d+\s*DAYS/)||[])[0])||90,paymentText:raw};if(/LETTER OF CREDIT|DOCUMENTARY CREDIT|L\/?C\s+AT\s+SIGHT|IRREVOCABLE\s+L\/?C/.test(u))return{paymentCode:'LC_SIGHT',usanceDays:0,paymentText:raw};if(/100\s*%\s*ADVANCE/.test(u))return{paymentCode:'ADV100',advancePct:100,paymentText:raw};const pct=firstNumber((u.match(/\d+(?:\.\d+)?\s*%\s*ADVANCE/)||[])[0]);if(/CASH AGAINST DOCUMENTS|\bCAD\b/.test(u))return{paymentCode:pct?'ADV_CAD':'CAD100',advancePct:pct,paymentText:raw};return pct?{paymentCode:'ADV_SCAN',advancePct:pct,paymentText:raw}:{paymentCode:'CUSTOM',customPayment:raw,paymentText:raw}}
function parsePackingLines(text,qty,containers,price){const out=[];for(const line of lines(text)){const m=line.match(/(\d+(?:\.\d+)?)\s*(KG|KGS|LB|LBS)\b/i);if(!m||!/BAG|SACK|PACK/i.test(line))continue;const size=num(m[1]),unit=/LB/i.test(m[2])?'LB':'KG',type=/JUTE/i.test(line)?'Jute Bags':/PAPER/i.test(line)?'Paper Bags':'PP Bags',brand=((line.match(/(?:BRAND|MARKING)\s*(?::|-)?\s*([A-Z0-9][A-Z0-9 &._\/-]{1,40})/i)||[])[1]||'').trim(),tare=firstNumber((line.match(/TARE[^\d]{0,8}(\d+(?:\.\d+)?)/i)||[])[1]),lineContainers=firstNumber((line.match(/(\d+)\s*(?:X\s*)?(?:CONTAINERS?|CNTRS?)/i)||[])[1]),lineQty=firstNumber((line.match(/(\d+(?:\.\d+)?)\s*(?:MT|MTS|M\/TONS?)/i)||[])[1]);if(!out.some(x=>x.size===size&&x.unit===unit&&x.type===type))out.push({type,size,unit,brand,tare,containers:lineContainers,weightPer:lineContainers&&lineQty?lineQty/lineContainers:0,price:num(price),freight:0,insurance:0,extraBagPct:0,masterBag:{enabled:/MASTER BAG/i.test(line),qty:firstNumber((line.match(/MASTER BAG[^\d]{0,12}(\d+)/i)||[])[1]),tare:firstNumber((line.match(/MASTER BAG.*?TARE[^\d]{0,8}(\d+(?:\.\d+)?)/i)||[])[1])}})}if(out.length===1){out[0].containers=out[0].containers||num(containers);out[0].weightPer=out[0].weightPer||(containers?num(qty)/num(containers):0)}if(out.length>1&&out.every(x=>!x.containers)&&containers%out.length===0)for(const x of out){x.containers=containers/out.length;x.weightPer=qty/containers}return out}
